"use client"

import * as React from "react"
import { useMemo, useSyncExternalStore, useEffect } from "react"
import { ResearchActivity, ResearchCurrent, ResearchPhase, ResearchPlanStep, ResearchProgress, ResearchStatus } from "@/components/ui/research-progress"

/** What a research agent streams: one `data-research` part, replaced on every update. */
interface ResearchRunData {
  status: ResearchStatus
  phase?: ResearchPhase
  plan: ResearchPlanStep[]
  sourcesRead: number
  sourcesFound: number
  current?: ResearchCurrent
  activity: ResearchActivity[]
}

const PLAN = [
  "Collect typographic guidance on line length",
  "Find controlled studies of reading on screen",
  "Compare speed, comprehension and preference",
  "Turn the findings into interface defaults",
]

function plan(active: number): ResearchPlanStep[] {
  return PLAN.map((title, i) => ({
    id: `step-${i}`,
    title,
    status: i < active ? "done" : i === active ? "active" : "pending",
  }))
}

/** Streaming state shared by text and reasoning parts. */
type ChatcnTextState = "streaming" | "done"

/** Assistant or user prose. */
type ChatcnTextPart = { type: "text"; text: string; state?: ChatcnTextState }

/** Model reasoning or thinking text. */
type ChatcnReasoningPart = {
  type: "reasoning"
  text: string
  id?: string
  state?: ChatcnTextState
}

/**
 * chatcn message contract.
 *
 * A structural mirror of AI SDK 7 `UIMessage` parts with no runtime import, so an AI SDK message
 * can be passed straight in while assistant-ui, LangGraph, AG-UI or a static mock can be adapted
 * to the same shape. A type test pins this file to the installed `ai` package.
 */

/** Lifecycle of a tool call, identical to AI SDK 7 tool part states. */
type ToolState =
  | "input-streaming"
  | "input-available"
  | "approval-requested"
  | "approval-responded"
  | "output-available"
  | "output-error"
  | "output-denied"

/** Human approval attached to a tool call. */
interface ChatcnApproval {
  id: string
  approved?: boolean
  /** Reason the user gave when responding (usually a denial). */
  reason?: string
  /** Reason the agent gave when asking. */
  requestReason?: string
}

/** A tool call: static (`tool-${name}`) or dynamic (`dynamic-tool` with `toolName`). */
type ChatcnToolPart = {
  type: `tool-${string}` | "dynamic-tool"
  toolCallId: string
  /** Present on `dynamic-tool` parts. Use `getToolName` to read the name of any tool part. */
  toolName?: string
  state: ToolState
  title?: string
  /** Partial while `input-streaming`, complete afterwards. */
  input?: unknown
  /** Raw input text received so far: a string while `input-streaming` (AI SDK types it loosely). */
  rawInput?: unknown
  output?: unknown
  errorText?: string
  approval?: ChatcnApproval
  providerExecuted?: boolean
  /** True while an `output-available` result is still being refined. */
  preliminary?: boolean
}

/** A web source cited by the response. */
type ChatcnSourceUrlPart = {
  type: "source-url"
  sourceId: string
  url: string
  title?: string
}

/** A document source cited by the response. */
type ChatcnSourceDocumentPart = {
  type: "source-document"
  sourceId: string
  mediaType: string
  title: string
  filename?: string
}

/** An attached or generated file (hosted URL or data URL). */
type ChatcnFilePart = { type: "file"; mediaType: string; url: string; filename?: string }

/** App-defined structured data (`data-${name}`), reconciled by `id`. */
type ChatcnDataPart<D = unknown> = { type: `data-${string}`; id?: string; data: D }

/** Boundary between agent steps. */
type ChatcnStepStartPart = { type: "step-start" }

/** Every part type chatcn renders natively. */
type ChatcnKnownPart =
  | ChatcnTextPart
  | ChatcnReasoningPart
  | ChatcnToolPart
  | ChatcnSourceUrlPart
  | ChatcnSourceDocumentPart
  | ChatcnFilePart
  | ChatcnDataPart
  | ChatcnStepStartPart

/** Any other part (for example AI SDK `custom` or `reasoning-file`): render a fallback, never crash. */
type ChatcnUnknownPart = { type: string; [key: string]: unknown }

/** Any message part. Narrow with `isKnownPart` first, then switch on `part.type`. */
type ChatcnPart = ChatcnKnownPart | ChatcnUnknownPart

/** A chat message, structurally compatible with AI SDK `UIMessage`. */
interface ChatcnMessage<P extends ChatcnPart = ChatcnPart> {
  id: string
  role: "system" | "user" | "assistant"
  parts: P[]
  metadata?: unknown
}

/** Points at a part: by index for prose, by `toolCallId` for tool calls. */
type ChatcnPartRef = { messageId: string; partIndex?: number; toolCallId?: string }

type Resolved = Readonly<Record<string, unknown>>

/** One timeline operation. */
type ChatcnStreamOp =
  | { op: "message"; message: ChatcnMessage }
  | { op: "part"; messageId: string; part: ChatcnPart }
  | ({ op: "text-delta"; delta: string } & ChatcnPartRef)
  | ({ op: "tool-input-delta"; delta: string } & ChatcnPartRef)
  | ({
      op: "patch"
      patch: Record<string, unknown> | ((resolved: Resolved) => Record<string, unknown>)
    } & ChatcnPartRef)
  | { op: "await"; key: string; auto?: { after: number; value: unknown } }

/** A timed, optionally guarded operation. */
type ChatcnStreamStep = ChatcnStreamOp & {
  at: number
  when?: (resolved: Resolved) => boolean
}

type Guard = ChatcnStreamStep["when"]

/** Options for chunked streaming builder steps. */
interface ChunkOptions {
  /** Delay between chunks in ms. */
  chunkMs?: number
  /** Approximate characters per chunk. */
  chunkSize?: number
}

/** Split text into chunks of about `size` characters, breaking after whitespace when possible. */
function chunkText(text: string, size: number, byWord = true): string[] {
  const chunks: string[] = []
  let i = 0
  while (i < text.length) {
    let end = Math.min(text.length, i + size)
    if (byWord && end < text.length) {
      const space = text.indexOf(" ", end)
      if (space !== -1 && space - end < size) end = space + 1
    }
    chunks.push(text.slice(i, end))
    i = end
  }
  return chunks
}

/**
 * Tolerant JSON parser for streaming tool input.
 *
 * Parses as much of a truncated JSON document as possible: unterminated strings keep their text,
 * open objects and arrays are closed, partial literals (`tr`, `nul`) are completed, partial numbers
 * (`12.`, `3e`) are trimmed and trailing commas are ignored. Keys without a value are dropped.
 * Single pass, no eval, no dependencies.
 */

/** Result of `parsePartialJson`. */
interface PartialJsonResult {
  /** Best-effort value, `undefined` when nothing could be parsed yet. */
  value: unknown
  /** True when the text held one finished JSON value (trailing commas tolerated). */
  complete: boolean
}

const NONE = Symbol("none")

type Parsed = unknown | typeof NONE

const LITERALS: Record<string, [string, unknown]> = {
  t: ["true", true],
  f: ["false", false],
  n: ["null", null],
}

const ESCAPES: Record<string, string> = {
  '"': '"',
  "\\": "\\",
  "/": "/",
  b: "\b",
  f: "\f",
  n: "\n",
  r: "\r",
  t: "\t",
}

const NUMBER_CHAR = /[-+.eE0-9]/

class Parser {
  i = 0
  /** Set when input ran out or a syntax error was hit; unwinds every open container. */
  stopped = false

  readonly s: string

  constructor(s: string) {
    this.s = s
  }

  ws(): void {
    const s = this.s
    while (this.i < s.length) {
      const c = s.charCodeAt(this.i)
      if (c !== 32 && c !== 10 && c !== 13 && c !== 9) return
      this.i++
    }
  }

  value(): Parsed {
    this.ws()
    const c = this.s[this.i]
    if (c === undefined) return this.stop()
    if (c === "{") return this.object()
    if (c === "[") return this.array()
    if (c === '"') return this.string()
    if (c === "-" || (c >= "0" && c <= "9")) return this.number()
    if (c in LITERALS) return this.literal(c)
    return this.stop()
  }

  stop(): typeof NONE {
    this.stopped = true
    return NONE
  }

  object(): Record<string, unknown> {
    const obj: Record<string, unknown> = {}
    this.i++
    while (true) {
      this.ws()
      const c = this.s[this.i]
      if (c === "}") {
        this.i++
        return obj
      }
      if (c === ",") {
        this.i++
        continue
      }
      if (c !== '"') {
        this.stop()
        return obj
      }
      const key = this.string()
      if (this.stopped) return obj
      this.ws()
      if (this.s[this.i] !== ":") {
        this.stop()
        return obj
      }
      this.i++
      const v = this.value()
      if (v !== NONE) {
        // defineProperty keeps a "__proto__" key from replacing the prototype.
        Object.defineProperty(obj, key, {
          value: v,
          enumerable: true,
          writable: true,
          configurable: true,
        })
      }
      if (this.stopped) return obj
      this.ws()
      const next = this.s[this.i]
      if (next === ",") this.i++
      else if (next !== "}") {
        this.stop()
        return obj
      }
    }
  }

  array(): unknown[] {
    const arr: unknown[] = []
    this.i++
    while (true) {
      this.ws()
      const c = this.s[this.i]
      if (c === "]") {
        this.i++
        return arr
      }
      if (c === ",") {
        this.i++
        continue
      }
      const v = this.value()
      if (v !== NONE) arr.push(v)
      if (this.stopped) return arr
      this.ws()
      const next = this.s[this.i]
      if (next === ",") this.i++
      else if (next !== "]") {
        this.stop()
        return arr
      }
    }
  }

  string(): string {
    const s = this.s
    let out = ""
    let start = ++this.i
    while (this.i < s.length) {
      const c = s[this.i]
      if (c === '"') {
        out += s.slice(start, this.i++)
        return out
      }
      if (c !== "\\") {
        this.i++
        continue
      }
      out += s.slice(start, this.i)
      start = this.i
      const e = s[this.i + 1]
      if (e === undefined) break
      if (e === "u") {
        const hex = s.slice(this.i + 2, this.i + 6)
        if (hex.length < 4) break
        const code = Number.parseInt(hex, 16)
        out += Number.isNaN(code) ? hex : String.fromCharCode(code)
        this.i += 6
      } else {
        out += ESCAPES[e] ?? e
        this.i += 2
      }
      start = this.i
    }
    // Ran out of input inside the string. A partial escape (start sits on it) is dropped.
    if (s[start] !== "\\") out += s.slice(start)
    this.stopped = true
    const last = out.charCodeAt(out.length - 1)
    return last >= 0xd800 && last <= 0xdbff ? out.slice(0, -1) : out
  }

  number(): Parsed {
    const s = this.s
    const start = this.i
    while (this.i < s.length && NUMBER_CHAR.test(s[this.i] as string)) this.i++
    const token = s.slice(start, this.i)
    // Trim a dangling sign, dot or exponent left by truncation (`12.`, `3e`, `-`).
    const trimmed = token.replace(/[-+.eE]+$/, "")
    if (trimmed !== token) this.stopped = true
    const n = Number(trimmed)
    return trimmed === "" || Number.isNaN(n) ? this.stop() : n
  }

  literal(first: string): Parsed {
    const [word, value] = LITERALS[first] as [string, unknown]
    const rest = this.s.slice(this.i, this.i + word.length)
    if (rest === word) {
      this.i += word.length
      return value
    }
    if (this.i + rest.length === this.s.length && word.startsWith(rest)) {
      this.i += rest.length
      this.stopped = true
      return value
    }
    return this.stop()
  }
}

/** Parse possibly truncated JSON, returning the best-effort value and whether it was complete. */
function parsePartialJson(text: string): PartialJsonResult {
  const p = new Parser(text)
  const v = p.value()
  if (!p.stopped) p.ws()
  return { value: v === NONE ? undefined : v, complete: !p.stopped && p.i === text.length }
}

/** True when an approval resolution value means yes (`true` or `{ approved: true }`). */
function isApproved(value: unknown): boolean {
  return (
    value === true ||
    (typeof value === "object" && value !== null && "approved" in value && value.approved === true)
  )
}

/** A built script. */
interface ChatcnScript {
  steps: ChatcnStreamStep[]
  duration: number
}

/** Fluent script builder. Every method appends steps at the builder's current time. */
class ChatcnScriptBuilder {
  private steps: ChatcnStreamStep[] = []
  private t = 0
  private messageId: string | null = null
  private partCount = new Map<string, number>()
  private tool: { id: string; guard: Guard } | null = null
  private ids = { message: 0, call: 0, approval: 0 }

  private push(op: ChatcnStreamOp, when?: Guard): this {
    this.steps.push(when ? { ...op, at: this.t, when } : { ...op, at: this.t })
    return this
  }

  private addMessage(role: ChatcnMessage["role"], id?: string): string {
    const messageId = id ?? `msg_${++this.ids.message}`
    this.partCount.set(messageId, 0)
    this.push({ op: "message", message: { id: messageId, role, parts: [] } })
    return messageId
  }

  private addPart(part: ChatcnPart): number {
    if (!this.messageId) this.messageId = this.addMessage("assistant")
    const messageId = this.messageId
    const index = this.partCount.get(messageId) ?? 0
    this.partCount.set(messageId, index + 1)
    this.push({ op: "part", messageId, part })
    return index
  }

  private toolRef(): { messageId: string; toolCallId: string } {
    if (!this.tool || !this.messageId) throw new Error("Call toolCall() before tool steps.")
    return { messageId: this.messageId, toolCallId: this.tool.id }
  }

  /** Advance the builder clock. */
  wait(ms: number): this {
    this.t += ms
    return this
  }

  /** Add a finished user message. */
  user(text: string, options: { id?: string } = {}): this {
    const id = this.addMessage("user", options.id)
    this.messageId = id
    this.addPart({ type: "text", text, state: "done" })
    this.messageId = null
    return this
  }

  /** Start an assistant message; later parts go into it. */
  assistant(options: { id?: string } = {}): this {
    this.messageId = this.addMessage("assistant", options.id)
    return this
  }

  /** Stream a text or reasoning part chunk by chunk, then mark it done. */
  text(text: string, options: ChunkOptions & { type?: "text" | "reasoning" } = {}): this {
    const { chunkMs = 30, chunkSize = 12, type = "text" } = options
    const partIndex = this.addPart({ type, text: "", state: "streaming" })
    const messageId = this.messageId as string
    for (const delta of chunkText(text, chunkSize)) {
      this.wait(chunkMs).push({ op: "text-delta", messageId, partIndex, delta })
    }
    return this.push({ op: "patch", messageId, partIndex, patch: { state: "done" } })
  }

  /** Stream a reasoning part. */
  reasoning(text: string, options: ChunkOptions = {}): this {
    return this.text(text, { ...options, type: "reasoning" })
  }

  /** Append any part as is. */
  part(part: ChatcnPart): this {
    this.addPart(part)
    return this
  }

  /** Start a tool call. Without `input` it begins in `input-streaming`. */
  toolCall(call: {
    name: string
    toolCallId?: string
    input?: unknown
    title?: string
    dynamic?: boolean
  }): this {
    const id = call.toolCallId ?? `call_${++this.ids.call}`
    const part: ChatcnToolPart = {
      type: call.dynamic ? "dynamic-tool" : `tool-${call.name}`,
      toolCallId: id,
      state: call.input === undefined ? "input-streaming" : "input-available",
    }
    if (call.dynamic) part.toolName = call.name
    if (call.title) part.title = call.title
    if (call.input !== undefined) part.input = call.input
    this.addPart(part)
    this.tool = { id, guard: undefined }
    return this
  }

  /** Stream the tool input as JSON in character chunks, then mark it `input-available`. */
  streamInput(input: unknown, options: ChunkOptions = {}): this {
    const { chunkMs = 40, chunkSize = 6 } = options
    const ref = this.toolRef()
    const raw = typeof input === "string" ? input : JSON.stringify(input)
    for (const delta of chunkText(raw, chunkSize, false)) {
      this.wait(chunkMs).push({ op: "tool-input-delta", ...ref, delta })
    }
    const value = typeof input === "string" ? parsePartialJson(input).value : input
    return this.push({
      op: "patch",
      ...ref,
      patch: { state: "input-available", input: value, rawInput: undefined },
    })
  }

  /**
   * Ask for approval and wait for `resolve(approvalId, value)`. Later tool steps only run when the
   * value is approving; a denial moves the call to `output-denied`. `auto` resolves on its own.
   */
  awaitApproval(
    options: {
      approvalId?: string
      requestReason?: string
      auto?: { after: number; value: unknown }
    } = {},
  ): this {
    const ref = this.toolRef()
    const id = options.approvalId ?? `approval_${++this.ids.approval}`
    const approval = options.requestReason ? { id, requestReason: options.requestReason } : { id }
    const approved: Guard = (r) => isApproved(r[id])
    this.push({ op: "patch", ...ref, patch: { state: "approval-requested", approval } })
    this.push(
      options.auto ? { op: "await", key: id, auto: options.auto } : { op: "await", key: id },
    )
    this.push(
      {
        op: "patch",
        ...ref,
        patch: { state: "approval-responded", approval: { ...approval, approved: true } },
      },
      approved,
    )
    this.push(
      {
        op: "patch",
        ...ref,
        patch: (r) => {
          const v = r[id]
          const reason = typeof v === "object" && v !== null && "reason" in v ? v.reason : undefined
          return { state: "output-denied", approval: { ...approval, approved: false, reason } }
        },
      },
      (r) => !isApproved(r[id]),
    )
    ;(this.tool as { guard: Guard }).guard = approved
    return this
  }

  /** Finish the tool call with output after `delayMs`. */
  output(output: unknown, options: { delayMs?: number } = {}): this {
    const ref = this.toolRef()
    return this.wait(options.delayMs ?? 400).push(
      { op: "patch", ...ref, patch: { state: "output-available", output } },
      this.tool?.guard,
    )
  }

  /** Fail the tool call after `delayMs`. */
  error(errorText: string, options: { delayMs?: number } = {}): this {
    const ref = this.toolRef()
    return this.wait(options.delayMs ?? 400).push(
      { op: "patch", ...ref, patch: { state: "output-error", errorText } },
      this.tool?.guard,
    )
  }

  /** Append a raw step at the current time. */
  step(op: ChatcnStreamOp, when?: Guard): this {
    return this.push(op, when)
  }

  /** Finish the script. */
  build(): ChatcnScript {
    return { steps: [...this.steps], duration: this.t }
  }
}

/** Start a script builder. */
function script(): ChatcnScriptBuilder {
  return new ChatcnScriptBuilder()
}

